}

function trasforma(input){
  var m = String(input.CondizioniPagamento).match(/(\d+)/);
  var gg = m ? parseInt(m[1], 10) : 0;
  var p = input.DataFattura.split('-');
  var d = new Date(Date.UTC(+p[0], +p[1] - 1, +p[2] + gg));
  return { scadenza: d.toISOString().slice(0, 10) };
}

